#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = (a); i < (b); i++)
#define all(v) (v).begin(), (v).end()

typedef long long ll;

const int MAXN = 600;

ll mod;
struct Num {
    ll v;
    Num() : v(0) {}
    Num(ll _v) { v = _v % mod; if (v < 0) v += mod; }
    Num operator+(const Num &b) const { return Num((v + b.v) % mod); }
    Num operator-(const Num &b) const { return Num((v - b.v + mod) % mod); }
    Num operator*(const Num &b) const { return Num((v * b.v) % mod); }
    Num pow(ll e) const {
        Num res(1), base(v);
        while (e > 0) {
            if (e & 1) res = res * base;
            base = base * base;
            e >>= 1;
        }
        return res;
    }
    Num inv() const { return pow(mod - 2); }
};

Num C[MAXN][MAXN];
Num A[MAXN], Cc[MAXN];
Num DP[MAXN][MAXN][2], DPC[MAXN][MAXN][2];

ll sum_range(ll l, ll r) {
    if (l > r) return 0;
    return (l + r) * (r - l + 1) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m >> mod;

    for (int i = 0; i <= m; ++i) {
        for (int j = 0; j <= i; ++j) {
            C[i][j] = (j == 0 || j == i) ? Num(1) : C[i - 1][j - 1] + C[i - 1][j];
        }
    }

    A[0] = Num(0); Cc[0] = Num(1);
    A[1] = Num(0); Cc[1] = Num(2);

    for (int i = 2; i <= m; ++i) {
        Num tmp(0), tmpc(0);
        for (int l = 0; l <= i; ++l) {
            int r = i - 1 - l;
            tmp = tmp + C[l] * C[r] * Num(sum_range(1, l) + sum_range(1, r))
                * C[i - 1][l] + (A[l] * C[r] + A[r] * C[l]) * C[i - 1][l] * Num(i + 1);
            tmpc = tmpc + C[l] * C[r] * Num(i + 1) * C[i - 1][l];
        }
        A[i] = tmp;
        Cc[i] = tmpc;
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= m; ++j)
            for (int k = 0; k < 2; ++k)
                DPC[i][j][k] = Num(0);
    DPC[0][0][0] = Num(1);

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            DPC[i][j][0] = DPC[i - 1][j][0] + DPC[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                DPC[i][j][1] = DPC[i][j][1] + C[k] * C[j][k] * DPC[i - k][j - k][0];
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            DP[i][j][0] = DP[i - 1][j][0] + DP[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                DP[i][j][1] = DP[i][j][1] + A[k] * C[j][k] * DPC[i - k][j - k][0]
                                + DP[i - k][j - k][0] * Cc[k] * C[j][k];
            }
        }
    }

    cout << (DP[n][m][0] + DP[n][m][1]).v << "\n";

    return 0;
}
